			JTextField wf = new JTextField(worldDrafts.containsKey(id) && (worldFocus == id || !worldDrafts.get(id).isEmpty()) ? worldDrafts.get(id) : shown, 4);
			wf.getDocument().addDocumentListener(new javax.swing.event.DocumentListener()
			{
				private void keep()
				{
