{
	private static final int COLOSSEUM_REGION = 7216; // the Fortis Colosseum arena
	private static final int ENGAGED_TICKS = 50; // about 30 seconds

	// raid bosses count towards their raid
	private static final String[][] RAID_NPCS = {
		{"chambers_of_xeric", "tekton", "vanguard", "vespula", "ice demon", "muttadile", "vasa nistirio", "skeletal mystic", "lizardman shaman", "deathly ranger", "deathly mage", "great olm", "abyssal portal"},
		{"theatre_of_blood", "the maiden of sugadinti", "pestilent bloat", "nylocas vasilias", "sotetseg", "xarpus", "verzik vitur"},
		{"tombs_of_amascut", "ba-ba", "kephri", "akkha", "zebak", "tumeken's warden", "elidinis' warden", "elidinis' warden"},
		// the Colosseum's wave enemies count as Sol Heredit (only names that live in the Colosseum alone, so a death elsewhere isn't mistaken for one)
		{"sol_heredit", "shockwave colossus", "javelin colossus", "serpent shaman", "jaguar warrior", "minotaur", "manticore"},
		// the Ferox Enclave PvP tutor: dying to him in the training challenges is recorded as a death to Pete Kayer
		{"pete_kayer", "pete kayer"},
		// bosses that fight under other names than the one on the kill count
		{"grotesque_guardians", "grotesque guardians", "dusk", "dawn"},
		{"the_gauntlet", "crystalline hunllef"},
		{"the_corrupted_gauntlet", "corrupted hunllef"},
		{"the_royal_titans", "branda the fire queen", "eldric the ice king"},
		// names from guides, not checked in game
		{"the_fractured_archive", "archive guardian", "bork", "smorks", "ezekiel", "dreadnoth", "dreadnoth the jellied", "moia", "xarth", "dagonhai", "dagon'hai", "ocellus"},
	};

	@Inject
	private Client client;

	@Inject
	private Dashboard dashboard;

	@Inject
	private Session session;

	@Inject
	private PinkLszConfig config;

	@Inject
	private Shots shots;

	private final Map<String, String> bosses = new HashMap<>();
	private int tick;
	private String lastBoss;
	private int lastBossTick;
	private WeakReference<Actor> lastTarget = new WeakReference<>(null); // the last thing you attacked, same idea as Dink

	private static String norm(String s)
	{
		String t = Text.removeTags(s == null ? "" : s).toLowerCase().replace(' ', ' ').trim();
		if (t.startsWith("the "))
		{
			t = t.substring(4);
		}
		return t.replaceAll("[^a-z0-9]", "");
	}

	private void build()
	{
		if (!bosses.isEmpty())
		{
			return;
		}
		for (Map.Entry<Integer, String> e : BossVarps.all())
		{
			bosses.put(norm(e.getValue()), e.getValue());
		}
		for (String[] raid : RAID_NPCS)
		{
			for (int i = 1; i < raid.length; i++)
			{
				bosses.put(norm(raid[i]), raid[0]);
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		tick++;
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}
		Actor target = me.getInteracting();
		if (target instanceof NPC)
		{
			build();
			String key = bosses.get(norm(target.getName()));
			if (key != null)
			{
				lastBoss = key;
				lastBossTick = tick;
			}
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged e)
	{
		if (e.getSource() == client.getLocalPlayer() && e.getTarget() instanceof NPC)
		{
			lastTarget = new WeakReference<>(e.getTarget());
		}
	}

	private String bossOf(Actor a)
	{
		if (a instanceof NPC && a.getName() != null)
		{
			build();
			return bosses.get(norm(a.getName()));
		}
		return null;
	}

	@Subscribe
	public void onActorDeath(ActorDeath e)
	{
		if (!config.trackDeaths() || !session.settled() || e.getActor() != client.getLocalPlayer())
		{
			return;
		}
		// last target, then anything attacking you (as Dink does), then the last boss you fought
		Player me = client.getLocalPlayer();
		String boss = bossOf(lastTarget.get());
		String seen = null;
		if (boss == null)
		{
			for (NPC n : client.getTopLevelWorldView().npcs())
			{
				// pets follow you around and "interact" with you too: they have no combat level and are never what killed you
				if (n.getInteracting() == me && n.getName() != null && n.getCombatLevel() > 0)
				{
					seen = n.getName();
					boss = bossOf(n);
					if (boss != null)
					{
						break;
					}
				}
			}
		}
		if (boss == null && lastBoss != null && tick - lastBossTick <= ENGAGED_TICKS)
		{
			boss = lastBoss;
		}
		// anything that kills you inside the Colosseum counts as Sol Heredit, whatever it is called
		if (boss == null && inColosseum(me))
		{
			boss = "sol_heredit";
		}
		lastBoss = null;
		lastTarget = new WeakReference<>(null);
		if (boss == null)
		{
			if (seen != null)
			{
				dashboard.note("Death not recorded: I don't know \"" + Text.removeTags(seen) + "\" as a boss. Tell the clan admins that name.");
			}
			return;
		}
		JsonObject d = new JsonObject();
		d.addProperty("boss", boss);
		shots.take(img ->
		{
			if (img != null)
			{
				d.addProperty("image", img);
			}
			dashboard.send(Kind.DEATH, d);
		});
	}

	private boolean inColosseum(Player me)
	{
		try
		{
			net.runelite.api.coords.WorldPoint wp = net.runelite.api.coords.WorldPoint.fromLocalInstance(client, me.getLocalLocation());
			return wp != null && wp.getRegionID() == COLOSSEUM_REGION;
		}
		catch (RuntimeException ex)
		{
			return false;
		}
	}

	public void forget()
	{
		lastBoss = null;
	}
}

package com.pinklsz.collect;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.pinklsz.net.Dashboard;
import com.pinklsz.net.Kind;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;

/** Drops from the RuneLite loot tracker. */
@Singleton
public class DropCollector
{
	@Inject
	private Dashboard dashboard;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Shots shots;

	private static final String LOOT_GROUP = "loottracker";
	private static final String LOOT_PREFIX = "drops_";
	private static final int PER_REQUEST = 20;

	/** The loot tracker's saved totals per boss, sent once per login. */
	public void sendHistory()
	{
		String profile = configManager.getRSProfileKey();
		if (profile == null)
		{
			return;
		}
		JsonArray batch = new JsonArray();
		for (String key : configManager.getRSProfileConfigurationKeys(LOOT_GROUP, profile, LOOT_PREFIX))
		{
			String full = key.startsWith(LOOT_PREFIX) ? key : LOOT_PREFIX + key;
			String json = configManager.getConfiguration(LOOT_GROUP, profile, full);
			if (json == null || json.isEmpty())
			{
				continue;
			}
			try
			{
				JsonObject o = new JsonParser().parse(json).getAsJsonObject();
				JsonElement drops = o.get("drops");
				if (drops == null || !drops.isJsonArray() || drops.getAsJsonArray().size() == 0)
				{
					continue;
				}
				String[] parts = full.substring(LOOT_PREFIX.length()).split("_", 2);
				JsonObject r = new JsonObject();
				r.addProperty("type", parts.length > 1 ? parts[0] : "");
				r.addProperty("name", parts.length > 1 ? parts[1] : parts[0]);
				r.addProperty("kills", o.has("kills") ? o.get("kills").getAsInt() : 0);
				r.add("drops", drops);
				batch.add(r);
			}
			catch (RuntimeException ignored)
			{
				continue;
			}
			if (batch.size() >= PER_REQUEST)
			{
				flush(batch);
				batch = new JsonArray();
			}
		}
		flush(batch);
	}

	private void flush(JsonArray batch)
	{
		if (batch.size() == 0)
		{
			return;
		}
		JsonObject d = new JsonObject();
		d.add("records", batch);
		dashboard.send(Kind.DROP_TOTALS, d);
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (event.getItems() == null || event.getItems().isEmpty())
		{
			return;
		}
		JsonArray items = new JsonArray();
		for (ItemStack s : event.getItems())
		{
			JsonObject o = new JsonObject();
			o.addProperty("id", s.getId());
			o.addProperty("qty", s.getQuantity());
			items.add(o);
		}
		long value = 0;
		for (ItemStack s : event.getItems())
		{
			value += (long) itemManager.getItemPrice(s.getId()) * s.getQuantity();
		}
		JsonObject data = new JsonObject();
		data.addProperty("value", value);
		data.addProperty("npc", event.getName());
		data.addProperty("qty", event.getAmount());
		data.addProperty("type", event.getType() == null ? "" : event.getType().name());
		data.add("items", items);
		boolean wanted = false;
		for (ItemStack s : event.getItems())
		{
			wanted |= dashboard.isWatched(s.getId());
		}
		if (value >= dashboard.dropMin() || wanted)
		{
			// valuable, or on the clan's watch list
			shots.take(img ->
			{
				if (img != null)
				{
					data.addProperty("image", img);
				}
				dashboard.send(Kind.DROP, data);
			});
		}
		else
		{
			dashboard.send(Kind.DROP, data);
		}
	}
}

package com.pinklsz.collect;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.pinklsz.PinkLszConfig;
import com.pinklsz.net.Dashboard;
import com.pinklsz.net.Kind;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Combat stats, worn gear, inventory, rune pouch and spellbook, so the clan site's DPS calculator
 * can load them ("Load from the Pink LSZ plugin"). Sent quietly, only when something changed,
 * after things have settled for a few seconds, and never more than once a minute.
 */
@Singleton
public class GearCollector
{
	private static final int INVENTORY = 93;
	private static final int WORN = 94;
	private static final int SETTLE_TICKS = 8; // about 5 seconds with nothing changing
	private static final long MIN_GAP_MS = 60 * 1000L;

	// rune pouch: which rune (an index into the rune enum) and how many, for each of the 4 slots
	private static final int[] POUCH_TYPE = {29, 1622, 1623, 14285};
	private static final int[] POUCH_QTY = {1624, 1625, 1626, 14286};
	private static final int RUNEPOUCH_RUNE_ENUM = 982;
	private static final int SPELLBOOK_VARBIT = 4070;

	// equipment slot index -> the calculator's slot name
	private static final String[] SLOT_NAMES = {
		"head", "cape", "neck", "weapon", "body", "shield", null, "legs", null, "hands", "feet", null, "ring", "ammo"
	};

	@Inject
	private Client client;

	@Inject
	private Dashboard dashboard;

	@Inject
	private PinkLszConfig config;

	private boolean dirty;
	private int quietTicks;
	private long lastSentAt;
	private String lastSent = "";
	private final java.util.EnumMap<Skill, Integer> levels = new java.util.EnumMap<>(Skill.class);

	public void markDirty()
	{
		dirty = true;
		quietTicks = 0;
	}

	public void forget()
	{
		dirty = false;
		quietTicks = 0;
		lastSent = "";
		lastSentAt = 0;
		levels.clear();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		if (e.getContainerId() == INVENTORY || e.getContainerId() == WORN)
		{
			markDirty();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		// only a real level change matters (not boosts going up and down)
		Integer was = levels.put(e.getSkill(), e.getLevel());
		if (was != null && was != e.getLevel())
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		int id = e.getVarbitId();
		if (id == SPELLBOOK_VARBIT)
		{
			markDirty();
			return;
		}
		for (int i = 0; i < 4; i++)
		{
			if (id == POUCH_TYPE[i] || id == POUCH_QTY[i])
			{
				markDirty();
				return;
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		if (!dirty || client.getGameState() != GameState.LOGGED_IN || !config.shareGear())
		{
			return;
		}
		quietTicks++;
		if (quietTicks < SETTLE_TICKS || System.currentTimeMillis() - lastSentAt < MIN_GAP_MS)
		{
			return;
		}
		JsonObject data = read();
		if (data == null)
		{
			return;
		}
		dirty = false;
		String sig = data.toString();
		if (sig.equals(lastSent))
		{
			return; // nothing new since the last one
		}
		lastSent = sig;
		lastSentAt = System.currentTimeMillis();
		dashboard.send(Kind.GEAR, data);
	}

	private JsonObject read()
	{
		JsonObject d = new JsonObject();

		JsonObject skills = new JsonObject();
		skills.addProperty("atk", client.getRealSkillLevel(Skill.ATTACK));
		skills.addProperty("str", client.getRealSkillLevel(Skill.STRENGTH));
		skills.addProperty("def", client.getRealSkillLevel(Skill.DEFENCE));
		skills.addProperty("ranged", client.getRealSkillLevel(Skill.RANGED));
		skills.addProperty("magic", client.getRealSkillLevel(Skill.MAGIC));
		skills.addProperty("prayer", client.getRealSkillLevel(Skill.PRAYER));
		skills.addProperty("hp", client.getRealSkillLevel(Skill.HITPOINTS));
		skills.addProperty("mining", client.getRealSkillLevel(Skill.MINING));
		skills.addProperty("herblore", client.getRealSkillLevel(Skill.HERBLORE));
		skills.addProperty("farming", client.getRealSkillLevel(Skill.FARMING));
		if (client.getRealSkillLevel(Skill.HITPOINTS) <= 0)
		{
			return null; // stats haven't loaded yet
		}
		d.add("skills", skills);

		JsonObject names = new JsonObject();
		JsonObject worn = new JsonObject();
		ItemContainer eq = client.getItemContainer(WORN);
		if (eq != null)
		{
			Item[] items = eq.getItems();
			for (int i = 0; i < items.length && i < SLOT_NAMES.length; i++)
			{
				if (SLOT_NAMES[i] == null || items[i].getId() <= 0)
				{
					continue;
				}
				JsonArray it = new JsonArray();
				it.add(items[i].getId());
				it.add(items[i].getQuantity());
				worn.add(SLOT_NAMES[i], it);
				name(names, items[i].getId());
			}
		}
		d.add("equipment", worn);

		JsonArray inv = new JsonArray();
		ItemContainer bag = client.getItemContainer(INVENTORY);
		for (int i = 0; i < 28; i++)
		{
			Item it = bag != null && i < bag.getItems().length ? bag.getItems()[i] : null;
			if (it == null || it.getId() <= 0)
			{
				inv.add((JsonObject) null);
				continue;
			}
			JsonArray p = new JsonArray();
			p.add(it.getId());
			p.add(it.getQuantity());
			inv.add(p);
			name(names, it.getId());
		}
		d.add("inv", inv);

		JsonArray pouch = new JsonArray();
		EnumComposition runes = client.getEnum(RUNEPOUCH_RUNE_ENUM);
		for (int i = 0; i < 4; i++)
		{
			int type = client.getVarbitValue(POUCH_TYPE[i]);
			int qty = client.getVarbitValue(POUCH_QTY[i]);
			int id = type > 0 && runes != null ? runes.getIntValue(type) : -1;
			if (id <= 0 || qty <= 0)
			{
				pouch.add((JsonObject) null);
				continue;
			}
			JsonArray p = new JsonArray();
			p.add(id);
			p.add(qty);
			pouch.add(p);
			name(names, id);
		}
		d.add("pouch", pouch);
		d.addProperty("book", client.getVarbitValue(SPELLBOOK_VARBIT));
		d.add("names", names);
		return d;
	}

	private void name(JsonObject names, int id)
	{
		String key = String.valueOf(id);
		if (!names.has(key))
		{
			names.addProperty(key, client.getItemDefinition(id).getName());
		}
	}
}

package com.pinklsz.collect;

import com.google.gson.JsonObject;
import com.pinklsz.net.Dashboard;
import com.pinklsz.net.Kind;
import com.pinklsz.net.Session;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/** Boss kill counts: changed ones after a kill, everything once per login. */
@Singleton
public class KillCollector
{
	@Inject
	private Client client;

	@Inject
	private Dashboard dashboard;

	@Inject
	private Session session;

	// The Fractured Archive has no kill count in the game's saved values, so each finished raid is counted from the chat line:
	// "Your completed The Fractured Archive count is: 3."  /  "Your completion count for The Fractured Archive is: 3."
	private static final Pattern ARCHIVE = Pattern.compile("^Your (?:completed |completion count for )(?:the )?fractured archive(?: count)?(?: is)?: ?([\\d,]+)\\.?$", Pattern.CASE_INSENSITIVE);

	private final Set<String> changed = new HashSet<>();

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if ((e.getType() != ChatMessageType.GAMEMESSAGE && e.getType() != ChatMessageType.SPAM) || !session.settled())
		{
			return;
		}
		Matcher m = ARCHIVE.matcher(Text.removeTags(e.getMessage()).trim());
		if (!m.matches())
		{
			return;
		}
		int count;
		try
		{
			count = Integer.parseInt(m.group(1).replace(",", ""));
		}
		catch (NumberFormatException ex)
		{
			return;
		}
		JsonObject kills = new JsonObject();
		kills.addProperty("the_fractured_archive", count);
		JsonObject data = new JsonObject();
		data.add("kills", kills);
		data.addProperty("completion", true); // one raid just finished: the site counts it from the one before
		dashboard.send(Kind.KILL_COUNTS, data);
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		if (!session.settled())
		{
			return;
		}
		String boss = BossVarps.bossFor(e.getVarpId());
		if (boss != null)
		{
			changed.add(boss);
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (changed.isEmpty())
		{
			return;
		}
		// several varps can change in one tick
		JsonObject kills = new JsonObject();
		for (String boss : changed)
		{
			int kc = BossVarps.read(client, boss);
			if (kc > 0)
			{
				kills.addProperty(boss, kc);
			}
		}
		changed.clear();
		push(kills);
	}

	public void sendSnapshot()
	{
		JsonObject kills = new JsonObject();
		for (Map.Entry<Integer, String> e : BossVarps.all())
		{
			int kc = BossVarps.read(client, e.getValue());
			if (kc > 0)
			{
				kills.addProperty(e.getValue(), kc);
			}
		}
		push(kills);
	}

	public void forget()
	{
		changed.clear();
	}

	private void push(JsonObject kills)
	{
		if (kills.size() == 0)
		{
			return;
		}
		JsonObject data = new JsonObject();
		data.add("kills", kills);
		dashboard.send(Kind.KILL_COUNTS, data);
	}
}

package com.pinklsz.collect;

import com.google.gson.JsonObject;
