/** The whole collection log (read when you open it) and each new item as you get it. */
@Singleton
public class LogCollector
{
	// fires once per owned item while the log's search runs
	private static final int ITEM_SCRIPT = 4100;
	private static final int CLOSE_SEARCH_SCRIPT = 2240;
	private static final int SEARCH_BUTTON = 40697932;
	private static final int LAST_ITEM_VARP = 4623;
	private static final int GIVE_UP_TICKS = 30;
	private static final long RESEND_MS = 10 * 60 * 1000L;
	private static final Pattern NEW_ITEM = Pattern.compile("New item added to your collection log: (.+)");

	// listed twice under different ids, counted once
	private static final Map<Integer, Integer> TWIN_ITEMS = Map.of(
		12013, 29472,
		12014, 29474,
		12015, 29476,
		12016, 29478
	);

	@Inject
	private Client client;

	@Inject
	private Dashboard dashboard;

	@Inject
	private Session session;

	private enum Phase
	{
		CLOSED, OPENED, READING
	}

	private Phase phase = Phase.CLOSED;
	private int readingTicks;
	private final Map<Integer, Integer> seen = new HashMap<>();
	private int reportedTotal = -1;

	private long lastSentAt;
	private int lastSentCount = -1;
	private long lastSentSum = -1;

	private int lastItemId;
	private boolean primed;
	private int pendingItemId;
	private int pendingWait;
	private String pendingName = "";

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e)
	{
		if (e.getGroupId() == InterfaceID.COLLECTION)
		{
			phase = Phase.OPENED;
			readingTicks = 0;
			reportedTotal = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (e.getGroupId() == InterfaceID.COLLECTION)
		{
			phase = Phase.CLOSED;
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired e)
	{
		if (phase != Phase.CLOSED && e.getScriptId() == ITEM_SCRIPT)
		{
			Object[] a = e.getScriptEvent().getArguments();
			seen.put((int) a[1], (int) a[2]);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		if (e.getVarpId() == VarPlayerID.COLLECTION_COUNT)
		{
			reportedTotal = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		}
		if (e.getVarpId() != LAST_ITEM_VARP)
		{
			return;
		}
		int id = client.getVarpValue(LAST_ITEM_VARP);
		if (id <= 0)
		{
			return;
		}
		// the login replay of the last item isn't a new one
		boolean fresh = session.settled() && primed && id != lastItemId;
		lastItemId = id;
		if (fresh)
		{
			pendingItemId = id;
			pendingWait = 2; // the chat line with the item's name arrives a moment either side of this
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (e.getType() != ChatMessageType.GAMEMESSAGE && e.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		Matcher m = NEW_ITEM.matcher(Text.removeTags(e.getMessage()));
		if (m.matches())
		{
			pendingName = m.group(1).trim();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (pendingItemId > 0 && --pendingWait <= 0)
		{
			sendNewItem();
		}
		if (phase == Phase.OPENED)
		{
			startReading();
		}
		else if (phase == Phase.READING)
		{
			continueReading();
		}
	}

	private void sendNewItem()
	{
		JsonObject d = new JsonObject();
		d.addProperty("item_id", pendingItemId);
		d.addProperty("name", pendingName);
		dashboard.send(Kind.COLLECTION_LOG_ITEM, d);
		pendingItemId = 0;
		pendingName = "";
	}

	private void startReading()
	{
		if (!session.settled())
		{
			phase = Phase.CLOSED;
			return;
		}
		seen.clear();
		// start listening before the search runs
		phase = Phase.READING;
		readingTicks = 0;
		// the game lists every owned item between opening and closing the search
		client.menuAction(-1, SEARCH_BUTTON, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(CLOSE_SEARCH_SCRIPT);
	}

	private void continueReading()
	{
		readingTicks++;
		if (reportedTotal < 0 || readingTicks > GIVE_UP_TICKS)
		{
			phase = Phase.CLOSED;
			dashboard.note("Couldn't read your collection log (" + countOwned() + " of " + Math.max(reportedTotal, 0) + " items). Close it and open it again.");
			return;
		}
		if (countOwned() != reportedTotal)
		{
			return;
		}
		phase = Phase.CLOSED;
		long sum = 0;
		for (Map.Entry<Integer, Integer> e : seen.entrySet())
		{
			sum += e.getKey() * 31L + e.getValue();
		}
		long now = System.currentTimeMillis();
		if (seen.size() == lastSentCount && sum == lastSentSum && now - lastSentAt < RESEND_MS)
		{
			return;
		}
		lastSentCount = seen.size();
		lastSentSum = sum;
		lastSentAt = now;
		JsonObject items = new JsonObject();
		for (Map.Entry<Integer, Integer> e : seen.entrySet())
		{
			items.addProperty(Integer.toString(e.getKey()), e.getValue());
		}
		JsonObject d = new JsonObject();
		d.add("items", items);
		dashboard.send(Kind.COLLECTION_LOG, d);
	}

	private int countOwned()
	{
		int n = seen.size();
		for (Map.Entry<Integer, Integer> t : TWIN_ITEMS.entrySet())
		{
			if (seen.containsKey(t.getKey()) && seen.containsKey(t.getValue()))
			{
				n--;
			}
		}
		return n;
	}

	public void forget()
	{
		phase = Phase.CLOSED;
		seen.clear();
		reportedTotal = -1;
		lastItemId = 0;
		primed = false;
		pendingItemId = 0;
		pendingName = "";
	}

	/** The varp is replayed at login, so remember it. */
	public void primeLastItem()
	{
		lastItemId = client.getVarpValue(LAST_ITEM_VARP);
		primed = true;
		reportedTotal = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
	}
}

package com.pinklsz.collect;

import com.google.gson.JsonObject;
import com.pinklsz.net.Dashboard;
import com.pinklsz.net.Kind;
import com.pinklsz.net.Session;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Completion times. Every finished boss or raid time the game prints is sent: new personal bests go to the PB records (with a screenshot),
 * other times only count for things like bingo speed tiles. The boss and the time come in two chat lines, in either order, so each waits briefly for the other.
 */
@Singleton
public class PbCollector
{
	private static final int WINDOW_TICKS = 6;
	private static final int RETRY_TICKS = 8;
	private static final int MAX_SHOT_TRIES = 12;

	// "Your Vorkath kill count is: 12."  /  "Your completed Theatre of Blood count is: 3."  /  "Your Prifddinas Agility Course lap count is: 4."
	private static final Pattern COUNT = Pattern.compile("^Your (?:completed )?(.+?)(?: (?:kill|harvest|lap|completion|success))? count is: ?[\\d,]+\\.?$", Pattern.CASE_INSENSITIVE);
	// "Your completion count for TzHaar-Ket-Rak's Fourth Challenge is: 3."
	private static final Pattern COUNT_FOR = Pattern.compile("^Your (?:completion|kill) count for (.+?) is: ?[\\d,]+\\.?$", Pattern.CASE_INSENSITIVE);
	// "Fight duration: 1:23.40 (new personal best)"  /  "Team size: 3 players Duration: 24:11.40 (new personal best)"  /  "... total completion time: 20:11.40 (new personal best)"
	private static final Pattern NEW_PB = Pattern.compile("(?:duration|completion time|subdued in|time)[: ]+(\\d+(?::\\d+)*(?:\\.\\d+)?).{0,40}\\(new personal best\\)", Pattern.CASE_INSENSITIVE);
	// any other finished time: "Fight duration: 1:31.20. Personal best: 1:23.40"  /  "Challenge time: 24:11. Total completion time: 30:02. Personal best: 22:40"
	private static final Pattern CHALLENGE_TIME = Pattern.compile("challenge time[: ]+(\\d+(?::\\d+)*(?:\\.\\d+)?)", Pattern.CASE_INSENSITIVE);
	private static final Pattern TOTAL_TIME = Pattern.compile("(?:completion time|subdued in)[: ]+(\\d+(?::\\d+)*(?:\\.\\d+)?)", Pattern.CASE_INSENSITIVE);
	private static final Pattern ANY_TIME = Pattern.compile("(?:fight duration|duration)[: ]+(\\d+(?::\\d+)*(?:\\.\\d+)?)", Pattern.CASE_INSENSITIVE);
	// the name in the time's own line, for the times that have no kill-count line after them: "Challenge complete: Bork. Duration: 2:12" / "The Fractured Archive: Total completion time: 21:40" / "Theatre of Blood total completion time: 27:39"
	private static final Pattern LINE_ROOM = Pattern.compile("^Challenge complete: (.+?)\\.", Pattern.CASE_INSENSITIVE);
	// "Wave 'The Maiden of Sugadinti' (Hard Mode) complete! Duration: 2:08.40": a Theatre of Blood room (the duration can come in the same message or the next)
	private static final Pattern WAVE = Pattern.compile("Wave '(.+?)'(?:\\s*\\((.*?)\\))?\\s*complete", Pattern.CASE_INSENSITIVE);
	private static final String[][] TOB_ROOMS = {{"maiden", "Maiden"}, {"bloat", "Bloat"}, {"nylocas", "Nylocas"}, {"sotetseg", "Sotetseg"}, {"xarpus", "Xarpus"}, {"verzik", "Verzik"}};
	private static final String[] TFA_ROOMS = {"archive guardian", "ezekiel", "bork", "moia", "dreadnoth", "dagon", "xarth", "ocellus"};
	private static final Pattern LINE_TOTAL = Pattern.compile("^(.+?):? (?:total )?(?:completion time|duration)", Pattern.CASE_INSENSITIVE);
	// group content where the game doesn't print the team size next to the time: the players in the instance are the team
	private static final Pattern GROUP = Pattern.compile("theatre of blood|tombs of amascut|fractured archive|chambers of xeric|colosseum", Pattern.CASE_INSENSITIVE);
	private static final Pattern TEAM = Pattern.compile("Team size: (?:(\\d+) players?|Solo)", Pattern.CASE_INSENSITIVE);

	@Inject
	private Client client;

	@Inject
	private Dashboard dashboard;

	@Inject
	private Session session;

	@Inject
	private Shots shots;

	private volatile int tick;
	private volatile int engagedTick = -100000; // the last time you hit something or got hit: spectators never do
	private static final int ENGAGED_TICKS = 500; // about 5 minutes

	private String boss;
	private int bossTick;
	private int lastTeam; // the last "Team size: N players" line the game printed, which can come in its own message
	private int lastTeamTick = -1000;
	private String waveBoss; // the Theatre of Blood room named in the last "Wave ... complete" line
	private int waveTick = -1000;
	private String lineBoss; // a name taken from the time's own line

	private String time;
	private int team;
	private boolean teamCounted; // the size was counted from nearby players rather than given by the game
	private String raw;
	private int timeTick;
	private boolean newPb;

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (e.getType() != ChatMessageType.GAMEMESSAGE && e.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String msg = Text.removeTags(e.getMessage());
		Matcher ts = TEAM.matcher(msg);
		if (ts.find())
		{
			lastTeam = ts.group(1) == null ? 1 : Integer.parseInt(ts.group(1));
			lastTeamTick = tick;
		}
		Matcher wv = WAVE.matcher(msg);
		if (wv.find())
		{
			String w = wv.group(1).toLowerCase();
			for (String[] r : TOB_ROOMS)
			{
				if (w.contains(r[0]))
				{
					boolean hard = wv.group(2) != null && wv.group(2).toLowerCase().contains("hard");
					waveBoss = "Theatre of Blood: " + (hard ? "Hard Mode: " : "") + r[1];
					waveTick = tick;
				}
			}
		}
		Matcher c = COUNT.matcher(msg);
		if (!c.matches())
		{
			c = COUNT_FOR.matcher(msg);
		}
		if (c.matches())
		{
			boss = c.group(1).trim();
			bossTick = tick;
			trySend();
			return;
		}
		Matcher p = NEW_PB.matcher(msg);
		boolean pb = p.find();
		if (!pb)
		{
			// a raid's challenge or total time wins over a room's own duration in the same line
			p = CHALLENGE_TIME.matcher(msg);
			if (!p.find())
			{
				p = TOTAL_TIME.matcher(msg);
				if (!p.find())
				{
					p = ANY_TIME.matcher(msg);
					if (!p.find())
					{
						return;
					}
				}
			}
		}
		if (!pb && newPb && time != null && tick - timeTick <= WINDOW_TICKS)
		{
			return; // a new personal best is already waiting to be sent: an ordinary time can't replace it
		}
		{
			newPb = pb;
			time = p.group(1);
			raw = msg;
			timeTick = tick;
			team = 0;
			teamCounted = false;
			lineBoss = null;
			Matcher ln = LINE_ROOM.matcher(msg);
			if (ln.find())
			{
				lineBoss = ln.group(1).trim();
			}
			else
			{
				ln = LINE_TOTAL.matcher(msg);
				if (ln.find() && ln.group(1).length() < 50 && !ln.group(1).toLowerCase().startsWith("challenge"))
				{
					lineBoss = ln.group(1).trim();
				}
			}
			if (waveBoss != null && tick - waveTick <= WINDOW_TICKS && !TOTAL_TIME.matcher(msg).find() && !CHALLENGE_TIME.matcher(msg).find())
			{
				lineBoss = waveBoss; // a Theatre of Blood room (the raid's own total is never a room)
				waveBoss = null;
			}
			else if (lineBoss != null)
			{
				String lb = lineBoss.toLowerCase();
				for (String r : TFA_ROOMS)
				{
					if (lb.contains(r))
					{
						lineBoss = "Fractured Archive: " + lineBoss; // a Fractured Archive boss
						break;
					}
				}
			}
			Matcher t = TEAM.matcher(msg);
			if (t.find())
			{
				team = t.group(1) == null ? 1 : Integer.parseInt(t.group(1));
				teamCounted = false;
			}
			else if (msg.toLowerCase().contains("colosseum") || (boss != null && boss.toLowerCase().contains("colosseum")) || (lineBoss != null && lineBoss.toLowerCase().contains("colosseum")))
			{
				team = 1; // the Colosseum is always solo
				teamCounted = false;
			}
			else if (GROUP.matcher(msg).find() || (boss != null && GROUP.matcher(boss).find()) || (lineBoss != null && GROUP.matcher(lineBoss).find()))
			{
				// not in the message: count the players in the instance (everyone there is on the team)
				// (this is a last resort, and the site is told the size was counted so staff can check it)
				int n = 0;
				for (Player ignored : client.getTopLevelWorldView().players())
				{
					n++; // the set has no size(), so count them
				}
				team = n >= 1 && n <= 100 ? n : 0; // a silly count is never sent
				teamCounted = team > 0;
			}
			trySend();
		}
	}

	// waiting for a screenshot that couldn't be taken yet
	private volatile JsonObject waiting;
	private volatile int waitingUntil;
	private int shotTries;

	@Subscribe
	public void onGameTick(GameTick e)
	{
		tick = tick + 1;
		if (waiting != null && tick >= waitingUntil)
		{
			capture();
		}
		// the boss line never came, send it anyway
		if (time != null && tick - timeTick > WINDOW_TICKS)
		{
			if (newPb || lineBoss != null || (boss != null && tick - bossTick <= WINDOW_TICKS * 2))
			{
				send(isRoom(lineBoss) ? lineBoss : (boss != null && tick - bossTick <= WINDOW_TICKS * 2 ? boss : (lineBoss != null ? lineBoss : "")));
			}
			else
			{
				forget(); // an ordinary time with no name at all: nothing to file it under
			}
		}
	}

	private void capture()
	{
		final JsonObject d = waiting;
		waiting = null;
		shots.take(img ->
		{
			if (img != null)
			{
				d.addProperty("image", img);
				dashboard.send(Kind.PERSONAL_BEST, d);
			}
			else
			{
				retry(d);
			}
		});
	}

	/** Try the screenshot again shortly; send without one only as a last resort. */
	private void retry(JsonObject d)
	{
		synchronized (this)
		{
			if (++shotTries > MAX_SHOT_TRIES)
			{
				dashboard.send(Kind.PERSONAL_BEST, d);
				return;
			}
			waitingUntil = tick + RETRY_TICKS;
			waiting = d;
		}
	}

	private void trySend()
	{
		if (time != null && isRoom(lineBoss))
		{
			send(lineBoss); // a room's own time is never filed under the whole raid
		}
		else if (time != null && boss != null && Math.abs(timeTick - bossTick) <= WINDOW_TICKS)
		{
			send(boss);
		}
	}

	private static boolean isRoom(String n)
	{
		return n != null && (n.startsWith("Theatre of Blood: ") || n.startsWith("Fractured Archive: "));
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied e)
	{
		if (e.getHitsplat().isMine() || e.getActor() == client.getLocalPlayer())
		{
			engagedTick = tick;
		}
	}

	private void send(String name)
	{
		// raid and group times only count if you were fighting in them: someone spectating a run sees the same messages but did not take part
		boolean group = name != null && (GROUP.matcher(name).find() || isRoom(name));
		boolean tookPart = !group || tick - engagedTick <= ENGAGED_TICKS;
		if (session.settled() && tookPart)
		{
			JsonObject d = new JsonObject();
			d.addProperty("boss", name);
			d.addProperty("time", time);
			// the game's own "Team size" line (in this message or one next to it) beats counting players
			if (lastTeam > 0 && Math.abs(lastTeamTick - timeTick) <= 30)
			{
				team = lastTeam;
				teamCounted = false;
			}
			d.addProperty("team_size", team);
			if (teamCounted)
			{
				d.addProperty("team_counted", true);
			}
			d.addProperty("raw", raw == null ? "" : raw);
			d.addProperty("is_pb", newPb);
			{
				// every time, personal best or not, only needs a screenshot if it would take 1st or 2nd on the clan record (or beat a bingo speed tile): ask the site first.
				// Only if the site can't be reached is the screenshot taken anyway, so a record that does reach staff has one.
				final JsonObject check = new JsonObject();
				check.addProperty("boss", name);
				check.addProperty("time", d.get("time").getAsString());
				check.addProperty("team_size", team);
				dashboard.call("pl_pb_check", check, reply ->
				{
					if (reply != null && reply.has("top") && !reply.get("top").getAsBoolean())
					{
						dashboard.send(Kind.PERSONAL_BEST, d); // can't reach the top two: nothing to review
					}
					else
					{
						synchronized (PbCollector.this)
						{
							shotTries = 0;
							waitingUntil = 0; // the next game tick takes the screenshot
							waiting = d;
						}
					}
				});
			}
		}
		time = null;
		boss = null;
		lineBoss = null;
		raw = null;
		team = 0;
		teamCounted = false;
		newPb = false;
	}

	public void forget()
	{
		time = null;
		boss = null;
		lineBoss = null;
		raw = null;
		team = 0;
		teamCounted = false;
		newPb = false;
	}
}

package com.pinklsz.collect;

import com.google.gson.JsonObject;
import com.pinklsz.net.Dashboard;
import com.pinklsz.net.Session;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Player kills during a clan event: when a player dies right after you were fighting them, or you die while a player was fighting you,
 * the killer and victim names are sent. Only runs while a tracked event is on, and the dashboard only keeps it if it falls inside one.
 */
@Singleton
public class PkCollector
{
	private static final int RECENT_TICKS = 8; // about 5 seconds

	@Inject
	private Client client;

	@Inject
	private Dashboard dashboard;

	@Inject
	private Session session;

	private final Map<String, Integer> attackers = new HashMap<>(); // players who were fighting you, and when
	private String targetName;
	private int targetTick;
	private int tick;
	private volatile boolean active;
	private volatile boolean wild;

	public void setActive(boolean on)
	{
		active = on;
	}

	public void setWild(boolean w)
	{
		wild = w;
	}

	public void forget()
	{
		attackers.clear();
		targetName = null;
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		tick++;
		Player me = client.getLocalPlayer();
		if (me == null || !active)
		{
			return;
		}
		Actor t = me.getInteracting();
		if (t instanceof Player && t.getName() != null)
		{
			targetName = Text.removeTags(t.getName());
			targetTick = tick;
		}
		for (Player p : client.getPlayers())
		{
			if (p != null && p != me && p.getName() != null && p.getInteracting() == me)
			{
				attackers.put(Text.removeTags(p.getName()), tick);
			}
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath e)
	{
		Player me = client.getLocalPlayer();
		if (!active || !session.settled() || me == null || !(e.getActor() instanceof Player) || e.getActor().getName() == null)
		{
			return;
		}
		String dead = Text.removeTags(e.getActor().getName());
		if (e.getActor() == me)
		{
			// who was fighting you most recently
			String killer = null;
			int best = -1;
			for (Map.Entry<String, Integer> a : attackers.entrySet())
			{
				if (tick - a.getValue() <= RECENT_TICKS && a.getValue() > best)
				{
					best = a.getValue();
					killer = a.getKey();
				}
			}
			if (killer != null)
			{
				report(killer, dead);
			}
			attackers.clear();
			return;
		}
		if (targetName != null && targetName.equals(dead) && tick - targetTick <= RECENT_TICKS)
		{
			report(Text.removeTags(me.getName()), dead);
			targetName = null;
		}
	}

	private void report(String killer, String victim)
	{
		JsonObject d = new JsonObject();
		d.addProperty("killer", killer);
		d.addProperty("victim", victim);
		d.addProperty("wild", wild);
		dashboard.call("pl_pk", d, r ->
		{
		});
	}
}

package com.pinklsz.collect;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.regex.Pattern;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.MemoryCacheImageOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.Text;

/**
 * Screenshots of the game as base64 JPEG. Private messages are hidden for the captured frame (as the Dink plugin does),
 * both the panel above the chatbox and any private message lines in it.
 */
@Singleton
public class Shots
{
	private static final int MAX_WIDTH = 2560;
	private static final long RECENT_MS = 45_000L;
	private static final int MAX_NAMES = 30;

	// "From Name: text" / "To Name: text", maybe after a timestamp
	private static final Pattern PRIVATE_LINE = Pattern.compile("^(?:\\[[0-9:]+\\]\\s*)?(?:From|To)\\s+[^:]{1,30}:.*");

	@Inject
	private DrawManager drawManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	// recent private message names; chat lines naming them are hidden too
	private final Deque<String> pmNames = new ArrayDeque<>();
	private volatile long lastPmAt;

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		ChatMessageType t = e.getType();
		if (t != ChatMessageType.PRIVATECHAT && t != ChatMessageType.PRIVATECHATOUT && t != ChatMessageType.MODPRIVATECHAT)
		{
			return;
		}
		lastPmAt = System.currentTimeMillis();
		String n = clean(e.getName());
		if (!n.isEmpty())
		{
			synchronized (pmNames)
			{
				pmNames.remove(n);
				pmNames.addFirst(n);
				while (pmNames.size() > MAX_NAMES)
				{
					pmNames.removeLast();
				}
			}
		}
	}

	/** Call on the client thread. The callback gets null if no safe picture could be made. */
	public void take(Consumer<String> done)
	{
		final List<Widget> hidden = new ArrayList<>();
		try
		{
			// the split private chat panel
			hide(client.getWidget(InterfaceID.PmChat.CONTAINER), hidden);
			// private message lines in the chatbox
			Widget[] roots = client.getWidgetRoots();
			if (roots != null)
			{
				for (Widget w : roots)
				{
					scan(w, 0, hidden);
				}
			}
		}
		catch (RuntimeException e)
		{
			show(hidden);
			done.accept(null);
			return;
		}
		if (hidden.isEmpty() && System.currentTimeMillis() - lastPmAt < RECENT_MS)
		{
			done.accept(null);
			return;
		}
		drawManager.requestNextFrameListener(image ->
		{
			show(hidden);
			executor.execute(() -> done.accept(encode(image)));
		});
		// in case no frame is drawn (minimised), don't leave messages hidden
		if (!hidden.isEmpty())
		{
			executor.schedule(() -> show(hidden), 3, java.util.concurrent.TimeUnit.SECONDS);
		}
	}

	private static void hide(Widget w, List<Widget> hidden)
	{
		if (w != null && !w.isHidden())
		{
			w.setHidden(true);
			hidden.add(w);
		}
	}

	private void show(List<Widget> hidden)
	{
		if (hidden.isEmpty())
		{
			return;
		}
		clientThread.invoke(() ->
		{
			for (Widget w : hidden)
			{
				w.setHidden(false);
			}
		});
	}

	private void scan(Widget w, int depth, List<Widget> hidden)
	{
		if (w == null || depth > 8 || w.isHidden())
		{
			return;
		}
		String t = w.getText();
		if (t != null && !t.isEmpty() && isPrivate(clean(t), Text.removeTags(t).replace(' ', ' ').trim()))
		{
			hide(w, hidden);
			return;
		}
		for (Widget[] kids : new Widget[][] {w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()})
		{
			if (kids == null)
			{
				continue;
			}
			for (Widget k : kids)
			{
				scan(k, depth + 1, hidden);
			}
		}
	}

	private boolean isPrivate(String lower, String plain)
	{
		if (PRIVATE_LINE.matcher(plain).matches())
		{
			return true;
		}
		synchronized (pmNames)
		{
			for (String n : pmNames)
			{
				if (lower.contains(n + ":") || lower.contains(n + " :"))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static String clean(String s)
	{
		return s == null ? "" : Text.removeTags(s).replace(' ', ' ').trim().toLowerCase();
	}

	private static String encode(Image image)
	{
		try
		{
			int w = image.getWidth(null);
			int h = image.getHeight(null);
			if (w <= 0 || h <= 0)
			{
				return null;
			}
			double scale = w > MAX_WIDTH ? (double) MAX_WIDTH / w : 1.0;
			int tw = (int) Math.round(w * scale);
			int th = (int) Math.round(h * scale);
			BufferedImage rgb = new BufferedImage(tw, th, BufferedImage.TYPE_INT_RGB);
			Graphics2D g = rgb.createGraphics();
			g.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION, java.awt.RenderingHints.VALUE_INTERPOLATION_BICUBIC);
			g.setRenderingHint(java.awt.RenderingHints.KEY_RENDERING, java.awt.RenderingHints.VALUE_RENDER_QUALITY);
			g.drawImage(image, 0, 0, tw, th, null);
			g.dispose();
			ImageWriter writer = ImageIO.getImageWritersByFormatName("jpg").next();
			ImageWriteParam p = writer.getDefaultWriteParam();
			p.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
			p.setCompressionQuality(0.93f);
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			try (MemoryCacheImageOutputStream ios = new MemoryCacheImageOutputStream(out))
			{
				writer.setOutput(ios);
				writer.write(null, new IIOImage(rgb, null, null), p);
			}
			writer.dispose();
			return Base64.getEncoder().encodeToString(out.toByteArray());
		}
		catch (Exception e)
		{
			return null;
		}
	}
}

package com.pinklsz.net;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.pinklsz.PinkLszConfig;
import com.pinklsz.PinkLszPlugin;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Collections;
import java.util.Deque;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.RuneScapeProfileType;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Everything sent to the dashboard goes through here, one request at a time. A failed request is retried
 * after a pause, and anything still failing after a few tries is dropped.
 */
@Singleton
public class Dashboard
{
	private static final Logger log = LoggerFactory.getLogger(Dashboard.class);
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final int MAX_TRIES = 4;
	private static final int RETRY_DELAY_SECONDS = 15;
	private static final int MAX_QUEUED = 300;
	private static final long MAX_QUEUED_CHARS = 24_000_000L; // screenshots are big
	private static final long INFO_GAP_MS = 20_000L;

	@Inject
	private OkHttpClient http;

	@Inject
	private PinkLszConfig config;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ScheduledExecutorService executor;

	private static final class Upload
	{
		final Kind kind;
		final String json;
		final int generation;
		int tries;

		Upload(Kind kind, String json, int generation)
		{
			this.kind = kind;
			this.json = json;
			this.generation = generation;
		}
	}

	private final Deque<Upload> queue = new ArrayDeque<>();
	private long queuedChars;
	private boolean busy;
	private int generation; // bumped on logout, so uploads from the last login are never sent

	private final Map<Kind, Long> lastInfo = new ConcurrentHashMap<>();
	private boolean warnedUrl;
	private boolean warnedRefused;
	private boolean connected;
	private static final long REFUSED_PAUSE_MS = 3 * 60 * 60 * 1000L; // a character the clan site refuses is left alone for a few hours
	private volatile String refusedName;
	private volatile long refusedAt;

	private volatile long dropMin = 1_000_000L;
	private volatile Set<Integer> watched = Collections.emptySet();

	/** Drops worth at least this much get a screenshot. */
	public long dropMin()
	{
		return dropMin;
	}

	/** Items the clan is looking for right now (e.g. a bingo board); these get a screenshot too. */
	public boolean isWatched(int itemId)
	{
		return watched.contains(itemId);
	}

	/** Can be called from any thread. */
	public void send(Kind kind, JsonObject data)
	{
		if (client.isClientThread())
		{
			enqueue(kind, data);
		}
		else
		{
			clientThread.invoke(() -> enqueue(kind, data));
		}
	}

	private void enqueue(Kind kind, JsonObject data)
	{
		Player me = client.getLocalPlayer();
		if (me == null || me.getName() == null)
		{
			return;
		}
		if (refusedName != null && refusedName.equalsIgnoreCase(me.getName()) && System.currentTimeMillis() - refusedAt < REFUSED_PAUSE_MS)
		{
			return; // not a clan member: nothing is sent for this character
		}
		JsonObject body = new JsonObject();
		body.addProperty("kind", kind.wire);
		body.addProperty("rsn", me.getName());
		body.addProperty("account_hash", client.getAccountHash());
		body.addProperty("account_type", client.getVarbitValue(VarbitID.IRONMAN));
		body.addProperty("profile", RuneScapeProfileType.getCurrent(client).name());
		body.addProperty("version", PinkLszPlugin.VERSION);
		body.addProperty("sent_at", System.currentTimeMillis());
		body.add("data", data);

		Upload u;
		synchronized (queue)
		{
			u = new Upload(kind, body.toString(), generation);
			queue.add(u);
			queuedChars += u.json.length();
			while (queue.size() > 1 && (queue.size() > MAX_QUEUED || queuedChars > MAX_QUEUED_CHARS))
			{
				queuedChars -= queue.poll().json.length();
			}
		}
		next();
	}

	private void next()
	{
		Upload u;
		synchronized (queue)
		{
			if (busy || queue.isEmpty())
			{
				return;
			}
			busy = true;
			u = queue.poll();
			queuedChars -= u.json.length();
		}
		upload(u);
	}

	private void finished()
	{
		synchronized (queue)
		{
			busy = false;
		}
		next();
	}

	/** Put it back at the front and wait before trying again. */
	private void retryLater(Upload u)
	{
		synchronized (queue)
		{
			if (++u.tries < MAX_TRIES && u.generation == generation)
			{
				queue.addFirst(u);
				queuedChars += u.json.length();
			}
		}
		executor.schedule(this::finished, RETRY_DELAY_SECONDS, TimeUnit.SECONDS);
	}

	private HttpUrl endpoint()
	{
		return endpoint("pl_ingest");
	}

	/** A page on the website (e.g. "/bingo/3"), built from the dashboard address in the settings; null if that address isn't valid. */
	public String siteUrl(String path)
	{
		HttpUrl u = endpoint("x");
		return u == null ? null : u.newBuilder().encodedPath(path).query(null).build().toString();
	}

	private HttpUrl endpoint(String action)
	{
		String base = config.dashboardUrl() == null ? "" : config.dashboardUrl().trim();
		if (!base.contains("://"))
		{
			base = "https://" + base;
		}
		HttpUrl url = HttpUrl.parse(base);
		if (url == null)
		{
			return null;
		}
		boolean local = "localhost".equals(url.host()) || "127.0.0.1".equals(url.host());
		if (!url.isHttps() && !local)
		{
			return null;
		}
		return url.newBuilder().encodedPath("/api/app.php").setQueryParameter("a", action).build();
	}

	private void upload(Upload u)
	{
		HttpUrl url = endpoint();
		if (url == null)
		{
			if (!warnedUrl)
			{
				warnedUrl = true;
				note("The dashboard address in the Pink LSZ settings isn't valid (it must start with https://).");
			}
			finished();
			return;
		}
		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", "PinkLSZ-RuneLite/" + PinkLszPlugin.VERSION)
			.post(RequestBody.create(JSON, u.json))
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("{} failed: {}", u.kind, e.getMessage());
				retryLater(u);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				boolean retry = false;
				try (Response r = response)
				{
					String text = r.body() == null ? "" : r.body().string();
					retry = handle(u, r.code(), text);
				}
				catch (IOException e)
				{
					retry = true;
				}
				if (retry)
				{
					retryLater(u);
				}
				else
				{
					finished();
				}
			}
		});
	}

	/** Returns true if the upload should be tried again later. */
	private boolean handle(Upload u, int code, String text)
	{
		if (code == 401 || code == 403)
		{
			String who = null;
			try
			{
				who = parse(u.json).get("rsn").getAsString();
			}
			catch (RuntimeException e)
			{
				// no name in the upload
			}
			if (code == 403 && who != null)
			{
				refusedName = who;
				refusedAt = System.currentTimeMillis();
				final String mark = "\"rsn\":" + new com.google.gson.JsonPrimitive(who).toString();
				synchronized (queue)
				{
					queue.removeIf(q ->
					{
						boolean same = q.json.contains(mark);
						if (same)
						{
							queuedChars -= q.json.length();
						}
						return same;
					});
				}
			}
			if (!warnedRefused)
			{
				warnedRefused = true;
				note(parse(text).has("error") ? parse(text).get("error").getAsString() : "The dashboard didn't accept this character.");
			}
			return false;
		}
		if (code == 429 || code >= 500)
		{
			return true;
		}
		if (code >= 400)
		{
			log.debug("{} rejected ({}): {}", u.kind, code, text);
			return false;
		}
		warnedRefused = false;
		JsonObject reply = parse(text);
		learn(reply);
		report(u.kind, reply);
		return false;
	}

	/** The dashboard only answers with JSON, but a proxy error page shouldn't break anything. */
	private static JsonObject parse(String text)
	{
		try
		{
			return new JsonParser().parse(text).getAsJsonObject();
		}
		catch (RuntimeException e)
		{
			return new JsonObject();
		}
	}

	private void learn(JsonObject reply)
	{
		if (reply.has("drop_min"))
		{
			dropMin = reply.get("drop_min").getAsLong();
		}
		if (reply.has("watch") && reply.get("watch").isJsonArray())
		{
			JsonArray ids = reply.get("watch").getAsJsonArray();
			Set<Integer> w = new HashSet<>();
			for (int i = 0; i < ids.size(); i++)
			{
				w.add(ids.get(i).getAsInt());
			}
			watched = w;
		}
	}

	private void report(Kind kind, JsonObject reply)
	{
		switch (kind)
		{
			case HELLO:
				if (!connected)
				{
					connected = true;
					boolean linked = !reply.has("linked") || reply.get("linked").getAsBoolean();
					if (!linked)
					{
						note("Add this character's name to your dashboard profile so your data shows up there.");
					}
				}
				if (reply.has("need_clog") && reply.get("need_clog").getAsBoolean())
				{
					note("Open your collection log once and it will sync to the dashboard.");
				}
				break;
			case PERSONAL_BEST:
				// only a personal best that went to staff is worth a message
				if (reply.has("pb") && "queued".equals(reply.get("pb").getAsString()) && reply.has("message"))
				{
					note(reply.get("message").getAsString());
				}
				break;
			case GEAR:
			case DROP:
				break; // happens on its own in the background (a drop is sent every time you get one): no chat line
			default:
				break; // a normal send says nothing: chat only speaks up when something is wrong
		}
	}

	/**
	 * One request that wants an answer (the TeamFinder panel), sent straight away and never retried.
	 * Can be called from any thread; the callback comes from a background thread. On a failure the reply has an "error".
	 */
	private volatile String callName; // the character from the last time the player was logged in

	/** The character name from the last time the player was logged in (null before the first login). */
	public String playerName()
	{
		return callName;
	}

	private volatile long callHash;

	public void call(String action, JsonObject data, java.util.function.Consumer<JsonObject> done)
	{
		clientThread.invoke(() ->
		{
			Player me = client.getLocalPlayer();
			GameState gs = client.getGameState();
			if (gs == GameState.LOGGED_IN && me != null && me.getName() != null)
			{
				callName = me.getName();
				callHash = client.getAccountHash();
			}
			else if (!((gs == GameState.HOPPING || gs == GameState.LOADING || gs == GameState.CONNECTION_LOST) && callName != null))
			{
				// only a real log out stops the check-ins: a world hop or loading screen keeps the team alive using the name from before
				done.accept(error("Log in to the game first."));
				return;
			}
			HttpUrl url = endpoint(action);
			if (url == null)
			{
				done.accept(error("The dashboard address in the Pink LSZ settings isn't valid."));
				return;
			}
			JsonObject body = data == null ? new JsonObject() : data;
			body.addProperty("rsn", callName);
			body.addProperty("account_hash", callHash);
			if (!body.has("world")) // a world the caller chose (hosting a team elsewhere) is kept; otherwise it is the world you are on
			{
				body.addProperty("world", client.getWorld());
			}
			body.addProperty("version", PinkLszPlugin.VERSION);
			Request request = new Request.Builder()
				.url(url)
				.header("User-Agent", "PinkLSZ-RuneLite/" + PinkLszPlugin.VERSION)
				.post(RequestBody.create(JSON, body.toString()))
				.build();
			http.newCall(request).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					done.accept(error("Couldn't reach the dashboard."));
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					JsonObject reply;
					try (Response r = response)
					{
						reply = parse(r.body() == null ? "" : r.body().string());
						if (r.code() >= 400 && !reply.has("error"))
						{
							reply = error("The dashboard answered with an error (" + r.code() + ").");
						}
					}
					catch (IOException e)
					{
						reply = error("Couldn't read the dashboard's answer.");
					}
					done.accept(reply);
				}
			});
		});
	}

	private final Map<String, java.awt.image.BufferedImage> roleIcons = new ConcurrentHashMap<>();
	private final Set<String> roleIconAsked = ConcurrentHashMap.newKeySet();

	/** The clan rank icon (the same picture the dashboard shows), or null while it is still being fetched; whenLoaded runs once it arrives. */
	public java.awt.image.BufferedImage roleIcon(String role, Runnable whenLoaded)
	{
		if (role == null || !role.matches("[a-z0-9_\\-]{1,40}"))
		{
			return null;
		}
		java.awt.image.BufferedImage have = roleIcons.get(role);
		if (have != null || !roleIconAsked.add(role))
		{
			return have;
		}
		HttpUrl base = endpoint("x");
		if (base == null)
		{
			return null;
		}
		HttpUrl url = base.newBuilder().encodedPath("/icons/roles/" + role + ".png").query(null).build();
		Request request = new Request.Builder().url(url).header("User-Agent", "PinkLSZ-RuneLite/" + PinkLszPlugin.VERSION).build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				roleIconAsked.remove(role);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						java.awt.image.BufferedImage img = javax.imageio.ImageIO.read(r.body().byteStream());
						if (img != null)
						{
							roleIcons.put(role, img);
							whenLoaded.run();
						}
					}
				}
				catch (IOException e)
				{
					roleIconAsked.remove(role);
				}
			}
		});
		return null;
	}

	private static JsonObject error(String text)
	{
		JsonObject o = new JsonObject();
		o.addProperty("error", text);
		return o;
	}

	/** Forget everything queued and per-login state. */
	public void reset()
	{
		synchronized (queue)
		{
			generation++;
			queue.clear();
			queuedChars = 0;
		}
		connected = false;
		lastInfo.clear();
	}

	/** Routine messages, only shown when "Show messages in chat" is on. */
	public void info(String text)
	{
		if (config.chatNotes())
		{
			note(text);
		}
	}

	/** A message from the clan leaders, shown whatever the "show messages in chat" setting is. {@code shown} runs once it is really in the chat. */
	/** "Name has started a ... team" / "Name is available to +1 ...": only the player's name is pink. */
	private static String teamLine(String text)
	{
		int i = text.indexOf(" has started a ");
		if (i <= 0)
		{
			i = text.indexOf(" is available to +1 ");
		}
		return i > 0 ? "<col=ef3d9a>" + text.substring(0, i) + "</col>" + text.substring(i) : text;
	}

	public void announce(String text, boolean team, Runnable shown)
	{
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", (team ? teamLine(net.runelite.client.util.Text.removeTags(text)) : "<col=ef3d9a>Pink LSZ announcement:</col> " + net.runelite.client.util.Text.removeTags(text)), "PinkLSZ");
				if (shown != null)
				{
					shown.run();
				}
			}
		});
	}

	public void note(String text)
	{
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=ef3d9a>Pink LSZ:</col> " + text, "PinkLSZ");
			}
		});
	}
}

package com.pinklsz.net;

/** What an upload is. {@code wire} is the name the dashboard knows it by, {@code label} is how chat messages describe it. */
public enum Kind
{
	HELLO("hello", null),
	DROP("loot", "a drop"),
	DROP_TOTALS("loot_total", "your saved drop totals"),
	KILL_COUNTS("kc", "kill counts"),
	COLLECTION_LOG("clog", "your collection log"),
	COLLECTION_LOG_ITEM("clog_new", "a new collection log item"),
	COMBAT_ACHIEVEMENTS("ca", "your combat achievements"),
	PERSONAL_BEST("pb", "a personal best"),
	DEATH("death", "a death"),
	GEAR("gear", null); // stats, worn gear and inventory for the DPS calculator: sent quietly

	final String wire;
	final String label;

	Kind(String wire, String label)
	{
		this.wire = wire;
		this.label = label;
	}
}

package com.pinklsz.net;

import javax.inject.Singleton;

/**
 * Whether the player for this login has loaded. The game replays a lot of varps while it logs you in, and those must not be
 * mistaken for kills or new collection log items, so collectors wait until the player (and their name) exists, the same way
 * the Valiance plugin does: the plugin calls {@link #loaded()} once the local player's name is populated.
 */
@Singleton
public class Session
{
	private volatile boolean loaded;

	public void loaded()
	{
		loaded = true;
	}

	public void loggedOut()
	{
		loaded = false;
	}

	public boolean settled()
	{
		return loaded;
	}
}

